// Activités, guides genevois, sécurité et un article écrit d'abord en allemand : 14 articles, 4 langues, écrits le 20 novembre 2026.
// Dates échelonnées dans DATES (articles.mjs). Sources lues le jour même : MétéoSuisse (orages, canicule), Société Suisse de Sauvetage (sauvetage,
// noyade secondaire, outils de sauvetage, gilets, rappels, eaux libres, saut après le soleil), État de Genève (Rhône, accès à l'eau),
// Wikipédia (Schiffsführerausweis, Silvaplanersee). Les loueurs viennent de locations.js (chacun avec sa source).
// Pas écrits, faute de source joignable : plages de sable, chiens, plongeoirs, coucher de soleil, familles (voir TODO.md).
import { SPOTS, lacDe, nomLac } from '../spots.js';
import { LOCATIONS } from '../locations.js';
import { ITEM } from './articles.lacs.mjs';
import { readFileSync } from 'node:fs';

const LS = ['fr', 'en', 'de', 'it'];
const SSS = (p, t) => [`Société Suisse de Sauvetage SSS, « ${t} »`, `https://www.slrg.ch/fr/${p}`];
const MS = (p, t) => [`MétéoSuisse, « ${t} »`, `https://www.meteosuisse.admin.ch/meteo/${p}.html`];
const S_SAUVETAGE = SSS('un-sauvetage-avec-un-minimum-de-risques', 'Un sauvetage avec un minimum de risques');
const S_SECONDAIRE = SSS('la-noyade-secondaire', 'La noyade secondaire');
const S_OUTILS = SSS('outils-de-sauvetage-nager-en-toute-securite-en-lac-et-en-riviere', 'Outils de sauvetage : nager en toute sécurité en lac et en rivière');
const S_GILET = SSS('votre-securite-assuree-grace-au-gilet-de-sauvetage-adequat', 'Votre sécurité assurée grâce au gilet de sauvetage adéquat');
const S_RAPPELS = SSS('les-rappels-sont-de-dangereux-pieges', 'Les rappels sont de dangereux pièges');
const S_EAUX_LIBRES = SSS('la-securite-en-eaux-libres', 'La sécurité en eaux libres');
